  $("login").hidden=true;$("dashboard").hidden=false;
  await load();
  const actions=document.querySelector(".header-actions");
  if(actions&&!document.getElementById("guac-link")){
   const link=document.createElement("a");link.id="guac-link";link.className="button-link";link.href="#";link.textContent="Open Guacamole";
   link.addEventListener("click",async event=>{event.preventDefault();const projectId=$("project").value;if(projectId||user?.admin)await launchGuacamole(projectId||0)});
   actions.prepend(link);
  }
  render();
