  const content=$("content"),state=el("div",undefined,"load-state"),retry=el("button","Retry","quiet");
  $("error").textContent=`Could not load the workspace: ${error.message}`;
  retry.type="button";retry.onclick=()=>start();
  state.append(el("p","Check the service connection, then try again."),retry);content.replaceChildren(state);
