function guacChoices(p,record={}){const group=el("div",undefined,"guac-user-grants"),teams=el("fieldset"),connections=el("fieldset");teams.append(el("legend","Teams"));connections.append(el("legend","Additional connections"));for(const team of p.team_ids||[]){const label=el("label",undefined,"check-choice"),input=document.createElement("input");input.type="checkbox";input.name="guac_team";input.value=team;input.checked=(record.teams||[]).includes(String(team));label.append(input,el("span",`Team ${team}`));teams.append(label)}const kinds=[["jumpbox",p.jump_boxes,"Jump box"],["vm",p.scenario_boxes,"VM"],["container",p.scenario_containers,"Container"]];for(const[kind,items,title]of kinds){for(const[key,item]of Object.entries(items||{})){const label=el("label",undefined,"check-choice"),input=document.createElement("input");input.type="checkbox";input.name="guac_connection";input.value=`${kind}:${key}`;input.checked=(record.connections||[]).includes(input.value);label.append(input,el("span",`${title} · ${item.display_name||item.name||key} · ${Number(item.team_id)===254?"Staging (Team 0)":`Team ${item.team_id}`} · ${teamSubnet(p.project_id,item.network_id??item.team_id)}`));connections.append(label)}}group.append(teams);if(connections.children.length>1)group.append(connections);return group}
