function renderReleaseRollouts(content,p){
 const records=Object.entries(p.release_rollouts||{});
 if(!records.length)return;
 const configuring=jobs.some(job=>job.project===Number(p.project_id)&&["release-apply","release-configure"].includes(job.operation)&&["queued","running"].includes(job.status));
 const pending=records.filter(([team,r])=>r.applied?.release_id&&r.applied.release_id===r.desired?.release_id&&r.health?.status!=="passed").map(([team])=>Number(team));
 if(pending.length){const resume=fixedAction("Continue configuration","release-configure",{teams:pending},"quiet");resume.dataset.help="Resume access, archived service configuration and health checks for the applied releases still awaiting acceptance. Existing machines are reused; no infrastructure plan is applied.";resume.disabled=configuring;content.append(resume)}
 content.append(table(["Team","Declared release","Applied release","Health",""],records.map(([team,r])=>{const actions=el("span");if(pending.includes(Number(team))){const resume=fixedAction("Continue","release-configure",{teams:[Number(team)]},"quiet");resume.disabled=configuring;resume.dataset.help=`Resume only Team ${team}'s applied release configuration and health checks; machines are retained.`;actions.append(resume)}return [team,r.desired?.version||"—",r.applied?.version||"Pending",r.health?.status||"Not checked",actions]})));

 for(const[team,r]of records){
  const history=el("details",undefined,"card"),summary=el("summary",`Team ${team} release history`);
  history.append(summary,table(["Event","Release","Result","When"],(r.history||[]).slice().reverse().map(event=>[
   event.event,event.version,event.status||event.action||"—",new Date(event.at).toLocaleString()])));
  content.append(history);
 }
}

