function helpForButton(b){const label=b.dataset.actionLabel||b.textContent.trim(),op=b.dataset.helpOperation;if(b.dataset.help)return b.dataset.help;if(op==="machine-state"||op==="box-state")return label==="Stop"?"Stop this box. Use for maintenance or testing. Its services and active sessions will be interrupted.":"Start this box. Use when it should be running or when testing startup order.";return operationHelp[op]||buttonHelp[label]||(b.classList.contains("table-link")?`Open ${label}. Use to inspect and manage this entry.`:`${label}. Use to open this control’s settings or details.`)}
const buttonTooltip=el("div",undefined,"button-tooltip");buttonTooltip.id="button-tooltip";buttonTooltip.role="tooltip";buttonTooltip.hidden=true;if(typeof buttonTooltip.showPopover==="function")buttonTooltip.setAttribute("popover","manual");document.body.append(buttonTooltip);let tooltipButton=null,tooltipTimer;
function adoptNativeHelp(button){const title=button.getAttribute("title");if(title){button.dataset.help=title;button.removeAttribute("title")}}
function hideButtonHelp(){clearTimeout(tooltipTimer);if(tooltipButton){const ids=(tooltipButton.getAttribute("aria-describedby")||"").split(/\s+/).filter(id=>id&&id!==buttonTooltip.id);if(ids.length)tooltipButton.setAttribute("aria-describedby",ids.join(" "));else tooltipButton.removeAttribute("aria-describedby")}tooltipButton=null;if(buttonTooltip.hasAttribute("popover")&&buttonTooltip.matches(":popover-open"))buttonTooltip.hidePopover();buttonTooltip.hidden=true}
function showButtonHelp(button){adoptNativeHelp(button);hideButtonHelp();tooltipButton=button;tooltipTimer=setTimeout(()=>{if(!button.isConnected)return;buttonTooltip.textContent=helpForButton(button);buttonTooltip.hidden=false;if(buttonTooltip.hasAttribute("popover"))buttonTooltip.showPopover();const ids=new Set((button.getAttribute("aria-describedby")||"").split(/\s+/).filter(Boolean));ids.add(buttonTooltip.id);button.setAttribute("aria-describedby",[...ids].join(" "));const r=button.getBoundingClientRect(),w=buttonTooltip.offsetWidth,h=buttonTooltip.offsetHeight;buttonTooltip.style.left=Math.max(8,Math.min(r.left,innerWidth-w-8))+"px";buttonTooltip.style.top=(r.bottom+h+16<innerHeight?r.bottom+8:Math.max(8,r.top-h-8))+"px"},350)}
const helpTarget="button,a.button-link,a.action-button";
document.addEventListener("mouseover",event=>{const button=event.target.closest(helpTarget);if(button&&button!==tooltipButton)showButtonHelp(button)});
document.addEventListener("mouseout",event=>{if(tooltipButton&&!tooltipButton.contains(event.relatedTarget)&&!buttonTooltip.contains(event.relatedTarget))hideButtonHelp()});
buttonTooltip.addEventListener("mouseleave",hideButtonHelp);
