function actionIcon(name){const svg=document.createElementNS("http://www.w3.org/2000/svg","svg"),path=document.createElementNS("http://www.w3.org/2000/svg","path");for(const [key,value]of Object.entries({viewBox:"0 0 24 24",class:"action-icon","aria-hidden":"true",fill:"none",stroke:"currentColor","stroke-width":"2.2","stroke-linecap":"round","stroke-linejoin":"round"}))svg.setAttribute(key,value);path.setAttribute("d",actionIconPaths[name]);svg.append(path);return svg}
function enhanceAction(button){
 adoptNativeHelp(button);if(button.classList.contains("notice-close")||button.closest(".sidebar"))return;
 const label=button.textContent.trim(),insideMenu=Boolean(button.closest(".action-menu")),inRow=Boolean(button.closest(".row-actions"));
 const common={Refresh:"refresh","Refresh activity":"refresh","Refresh templates":"refresh","Reload snapshot":"refresh",Close:"close",First:"first",Previous:"previous",Next:"next",Last:"last","More actions":"more","Project settings":"settings","Remove from setup":"trash"};
 const rowIcons={"Remote access":"monitor",Edit:"edit",Start:"start",Stop:"stop",Remove:"trash",Validate:"check",Users:"users"};
 const name=common[label]||(inRow?rowIcons[label]:null)||(label==="Stop task"?"stop":null)||(label==="← All teams"||label==="← Users"?"back":null)||(label==="Open Guacamole"?"external":null);
 if(/^(Delete|Remove|Clean up|Cancel)/.test(label))button.classList.add("danger-action");
 if(!name||button.dataset.actionIcon===label&&button.querySelector(".action-icon"))return;
 button.dataset.actionLabel=label;button.dataset.actionIcon=label;const only=!insideMenu&&(Boolean(common[label])||inRow||label==="Stop task");
 if(!button.hasAttribute("aria-label"))button.setAttribute("aria-label",label);
 const text=el("span",label,only?"visually-hidden":"action-label");button.replaceChildren(actionIcon(name),text);button.classList.toggle("icon-button",only);button.classList.add("has-action-icon");
}
function enhanceActions(root=document){if(root.matches?.(helpTarget))enhanceAction(root);root.querySelectorAll?.(helpTarget).forEach(enhanceAction)}
const actionEnhancer=new MutationObserver(records=>{for(const record of records){if(record.type==="attributes")enhanceAction(record.target);else for(const node of record.addedNodes){if(node.nodeType===1)enhanceActions(node);else if(node.parentElement?.matches(helpTarget))enhanceAction(node.parentElement)}}});actionEnhancer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["title"]});enhanceActions();

