/* Keep keyboard navigation in the active dialog. Polling never changes focus. */
document.addEventListener("keydown",event=>{
 const dialogs=[...document.querySelectorAll('[role="dialog"][aria-modal="true"]')].filter(node=>node.getClientRects().length);
 const dialog=dialogs[dialogs.length-1];if(!dialog)return;
 const controls=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled):not([type="hidden"]),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(node=>node.getClientRects().length);
 if(event.key==="Tab"&&controls.length){const first=controls[0],last=controls[controls.length-1];if(!dialog.contains(document.activeElement)){event.preventDefault();(event.shiftKey?last:first).focus()}else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
 else if(event.key==="Escape"&&!document.querySelector('.action-menu:popover-open')){const close=controls.find(node=>node.id==="close-action"||node.id==="close-job"||node.textContent.trim()==="Close");if(close){event.preventDefault();close.click()}}
});
